gek(){return"\u10d3\u10d0\u10d0\u10db\u10d0\u10e2\u10d4\u10d7 \u10d7\u10e5\u10d5\u10d4\u10dc\u10d8 \u10d4\u10da.\u10e4\u10dd\u10e1\u10e2\u10d0"},
